<script type="module">
import * as THREE from './three.module.js';

// ---------- world config ----------
const S = 72;                 // grid size (72x72 voxel columns)
const VOX = 1;                // voxel unit
const half = S/2;

// ---------- heightfield ----------
const hMap = new Int8Array(S*S).fill(3);   // base ground height
const surf = new Uint8Array(S*S);          // 0 grass 1 sand 2 water 3 stone

function idx(x,z){ return z*S+x; }
function inB(x,z){ return x>=0&&z>=0&&x<S&&z<S; }

// hills / valley via layered value noise
function hash(x,z){ let n=x*374761393+z*668265263; n=(n^(n>>13))*1274126177; return ((n^(n>>16))>>>0)/4294967295; }
function smooth(t){ return t*t*(3-2*t); }
function vnoise(x,z){
  const xi=Math.floor(x), zi=Math.floor(z), xf=smooth(x-xi), zf=smooth(z-zi);
  const a=hash(xi,zi), b=hash(xi+1,zi), c=hash(xi,zi+1), d=hash(xi+1,zi+1);
  return a+(b-a)*xf+(c-a)*zf+(a-b-c+d)*xf*zf;
}
function fbm(x,z){ return vnoise(x*0.045,z*0.045)*1.0 + vnoise(x*0.11,z*0.11)*0.45 + vnoise(x*0.23,z*0.23)*0.2; }

// river path: winding curve from z=0 edge to z=S-1 edge
const riverPts=[];
{
  for(let i=0;i<=S;i++){
    const t=i/S;
    const x = half + Math.sin(t*Math.PI*1.6+0.7)*16 + Math.sin(t*Math.PI*4.1)*4;
    riverPts.push({x, z:i});
  }
}
function riverDist(x,z){
  let m=1e9;
  for(let i=0;i<riverPts.length-1;i++){
    const a=riverPts[i], b=riverPts[i+1];
    const dx=b.x-a.x, dz=b.z-a.z;
    const L2=dx*dx+dz*dz;
    let t=((x-a.x)*dx+(z-a.z)*dz)/L2; t=Math.max(0,Math.min(1,t));
    const px=a.x+dx*t, pz=a.z+dz*t;
    const d=(x-px)*(x-px)+(z-pz)*(z-pz);
    if(d<m)m=d;
  }
  return Math.sqrt(m);
}

// base terrain shape: valley along the river, hills elsewhere
for(let z=0;z<S;z++)for(let x=0;x<S;x++){
  const rd = riverDist(x,z);
  const n = fbm(x,z);
  let h = 4 + Math.round(n*10);          // 4..14 rolling hills
  // carve valley near river
  const valley = Math.max(0, 1 - rd/14);
  h = h - Math.round(valley*6) + 2;
  if(rd < 2.6) h = 1;                    // river bed
  hMap[idx(x,z)] = Math.max(1, h);
}

// smooth pass to avoid harsh steps
for(let it=0;it<2;it++){
  const tmp = Int8Array.from(hMap);
  for(let z=1;z<S-1;z++)for(let x=1;x<S-1;x++){
    hMap[idx(x,z)] = Math.round((tmp[idx(x,z)]*2 + tmp[idx(x-1,z)]+tmp[idx(x+1,z)]+tmp[idx(x,z-1)]+tmp[idx(x,z+1)])/6);
  }
}

// surface classification
for(let z=0;z<S;z++)for(let x=0;x<S;x++){
  const i=idx(x,z), h=hMap[i];
  const rd=riverDist(x,z);
  if(h<=1 && rd<3.2){ surf[i]=2; }                 // water
  else if(rd<4.6 || h<=2){ surf[i]=1; }            // sand near water
  else surf[i]=0;
}

// village flat plateau at centre
const VILL_R = 15;
const vcx = half, vcz = half;
{
  // pick plateau height = median-ish of centre area
  let sum=0,cnt=0;
  for(let z=vcz-6;z<=vcz+6;z++)for(let x=vcx-6;x<=vcx+6;x++){ sum+=hMap[idx(x,z)]; cnt++; }
  const vh = Math.round(sum/cnt);
  for(let z=0;z<S;z++)for(let x=0;x<S;x++){
    const d=Math.hypot(x-vcx,z-vcz);
    if(d<VILL_R+3){
      const t=Math.min(1,(VILL_R+3-d)/3); // blend edge
      const i=idx(x,z);
      hMap[i]=Math.round(hMap[i]*(1-t)+vh*t);
      if(d<VILL_R && surf[i]!==2) surf[i]=0;
    }
  }
}
const villageH = (()=>{ let s=0,c=0; for(let z=vcz-6;z<=vcz+6;z++)for(let x=vcx-6;x<=vcx+6;x++){s+=hMap[idx(x,z)];c++;} return Math.round(s/c); })();

// ---------- instanced geometry helpers ----------
const renderer = new THREE.WebGLRenderer({antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.setSize(innerWidth,innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();

const camera = new THREE.PerspectiveCamera(50, innerWidth/innerHeight, 0.1, 400);

// lights
const hemi = new THREE.HemisphereLight(0xbfe3ff, 0x8a7a5a, 0.9);
scene.add(hemi);
const sun = new THREE.DirectionalLight(0xfff2d8, 1.6);
sun.position.set(40,60,25);
sun.castShadow = true;
sun.shadow.mapSize.set(2048,2048);
const sc = sun.shadow.camera;
sc.left=-60; sc.right=60; sc.top=60; sc.bottom=-60; sc.near=1; sc.far=200;
scene.add(sun);
const moon = new THREE.DirectionalLight(0x8fa8ff, 0.0);
moon.position.set(-30,50,-40);
scene.add(moon);

// sky dome via big sphere shader-free: use scene.background color swap
scene.background = new THREE.Color(0x87ceeb);
scene.fog = new THREE.Fog(0x87ceeb, 90, 220);

// ---------- merged voxel chunks ----------
// We merge boxes into BufferGeometry manually (positions, normals, colors) per material group.
// Simpler approach: use InstancedMesh per material type with per-instance color.

const boxGeo = new THREE.BoxGeometry(1,1,1);
const faceColors = boxGeo.attributes.position.count; // 24 verts

function makeInstanced(count, mat){
  const m = new THREE.InstancedMesh(boxGeo, mat, count);
  m.castShadow = true; m.receiveShadow = true;
  m.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  return m;
}

const mats = {
  grass : new THREE.MeshLambertMaterial({color:0xffffff}),
  dirt  : new THREE.MeshLambertMaterial({color:0xffffff}),
  stone : new THREE.MeshLambertMaterial({color:0xffffff}),
  sand  : new THREE.MeshLambertMaterial({color:0xffffff}),
  water : new THREE.MeshLambertMaterial({color:0x3a86c8, transparent:true, opacity:0.85}),
  wood  : new THREE.MeshLambertMaterial({color:0xffffff}),
  leaf  : new THREE.MeshLambertMaterial({color:0xffffff}),
  roofR : new THREE.MeshLambertMaterial({color:0xffffff}),
  roofB : new THREE.MeshLambertMaterial({color:0xffffff}),
  roofG : new THREE.MeshLambertMaterial({color:0xffffff}),
  roofY : new THREE.MeshLambertMaterial({color:0xffffff}),
  wallA : new THREE.MeshLambertMaterial({color:0xffffff}),
  wallB : new THREE.MeshLambertMaterial({color:0xffffff}),
  wallC : new THREE.MeshLambertMaterial({color:0xffffff}),
  wallD : new THREE.MeshLambertMaterial({color:0xffffff}),
  path  : new THREE.MeshLambertMaterial({color:0xffffff}),
  window: new THREE.MeshBasicMaterial({color:0xffcf6e}),
  trunk : new THREE.MeshLambertMaterial({color:0xffffff}),
};

// collect instances: {mat, x,y,z, sx,sy,sz, color}
const instances = [];
function add(mat, x,y,z, sx=1,sy=1,sz=1, color=null){
  instances.push({m:mat, x,y,z, sx,sy,sz, c:color});
}

// ---------- build terrain voxels ----------
// For performance: for each column, render top voxel + one tall "column" box down to bedrock.
const terrainLists = {grass:[],dirt:[],stone:[],sand:[],water:[]};
for(let z=0;z<S;z++)for(let x=0;x<S;x++){
  const i=idx(x,z), h=hMap[i], s=surf[i];
  const px=x-half+0.5, pz=z-half+0.5;
  const jitter = (hash(x*7+1,z*13+5)-0.5)*0.12;
  if(s===2){
    terrainLists.water.push({x:px,y:1.0,z:pz, sx:1,sy:0.6,sz:1, c:0x3a86c8});
    continue;
  }
  // top block
  let topMat, topCol;
  if(s===1){ topMat='sand'; topCol=0xd8c68a; }
  else { topMat='grass'; topCol = new THREE.Color().setHSL(0.29, 0.5, 0.34+jitter*0.5); }
  terrainLists[topMat].push({x:px,y:h-0.5+0.5,z:pz, sx:1,sy:1,sz:1, c:topCol});
  // column body: dirt/stone down to y=0
  const bodyH = h-1;
  if(bodyH>0){
    const mat = bodyH>3 ? 'stone':'dirt';
    const col = mat==='stone'?0x8d8d92:0x7a5a3a;
    terrainLists[mat].push({x:px, y:bodyH/2, z:pz, sx:1, sy:bodyH, sz:1, c:col});
  }
}

// ---------- stone path ----------
// connect village buildings with winding stone path
const pathCells = new Set();
function carvePath(x0,z0,x1,z1){
  let x=x0, z=z0;
  let guard=0;
  while((x!==x1||z!==z1) && guard++<400){
    pathCells.add(idx(x,z));
    if(x!==x1 && (z===z1 || hash(x*3,z*7)>0.5)) x+=Math.sign(x1-x);
    else if(z!==z1) z+=Math.sign(z1-z);
    else x+=Math.sign(x1-x);
  }
  pathCells.add(idx(x1,z1));
}
// path also reaches edges for flavor? keep inside village.
const pathPts = [
  [vcx-9, vcz-8],[vcx+8, vcz-9],[vcx+10, vcz+6],[vcx-8, vcz+9],[vcx, vcz],[vcx-10, vcz-2],[vcx+4, vcz+10]
];
for(let i=0;i<pathPts.length-1;i++) carvePath(pathPts[i][0],pathPts[i][1],pathPts[i+1][0],pathPts[i+1][1]);

// convert path cells to stone slabs slightly above grass
for(const ci of pathCells){
  const x=ci%S, z=(ci/S)|0;
  const i=idx(x,z);
  if(surf[i]===2) continue;
  surf[i]=3;
  // replace top voxel visual: add path slab above grass top
  const h=hMap[i];
  terrainLists.path.push({x:x-half+0.5, y:h+0.04, z:z-half+0.5, sx:0.92, sy:0.12, sz:0.92, c:new THREE.Color().setHSL(0.08,0.06,0.42+ (hash(x,z)-0.5)*0.1)});
}

// ---------- buildings ----------
// 12 buildings, 4 design families. Place on plateau avoiding path cells and river.
const buildings=[];
const usedCells = new Set();
function reserveFootprint(cx,cz,w,d){
  for(let z=cz-d;z<=cz+d;z++)for(let x=cx-w;x<=cx+w;x++){
    if(!inB(x,z)) return false;
    const i=idx(x,z);
    if(surf[i]===2||pathCells.has(i)) return false;
    if(usedCells.has(i)) return false;
  }
  return true;
}
function occupy(cx,cz,w,d){
  for(let z=cz-d;z<=cz+d;z++)for(let x=cx-w;x<=cx+w;x++) usedCells.add(idx(x,z));
}

function buildHouse(cx,cz,w,d,wallMat,roofMat,roofKind,floors){
  const gy = villageH; // plateau ground
  occupy(cx,cz,w+1,d+1);
  buildings.push({cx,cz,w,d,gy});
  const wx = cx-half+0.5, wz = cz-half+0.5;
  // walls: ring of blocks, floors tall
  const H = floors*3 + 1;
  for(let fy=0; fy<H; fy++){
    const y = gy + fy + 0.5;
    for(let dz=-d; dz<=d; dz++)for(let dx=-w; dx<=w; dx++){
      const edge = (Math.abs(dx)===w||Math.abs(dz)===d);
      if(!edge) continue;
      const isDoor = (dz===d && dx===0 && fy<2);
      const winX = (Math.abs(dz)===d && dx!==0 && fy>0 && fy%2===1 && ((dx+dz)&1)===0);
      const winZ = (Math.abs(dx)===w && dz!==0 && fy>0 && fy%2===1 && ((dx+dz)&1)===0);
      if(isDoor) continue;
      if(winX||winZ){ add('window', wx+dx, y, wz+dz, 0.55,0.7,0.55); continue; }
      add(wallMat, wx+dx, y, wz+dz, 1,1,1, wallColorOf(wallMat,dx,dz,fy));
    }
  }
  // roof
  const ry = gy + H;
  if(roofKind===0){ // pyramid
    let rw=w, rd=d, lvl=0;
    while(rw>=0&&rd>=0){
      for(let dz=-rd;dz<=rd;dz++)for(let dx=-rw;dx<=rw;dx++){
        if(Math.abs(dx)!==rw||Math.abs(dz)!==rd|| (rw===0&&rd===0)) {
          if(Math.abs(dx)===rw||Math.abs(dz)===rd|| (rw===0&&rd===0))
            add(roofMat, wx+dx, ry+lvl+0.5, wz+dz, 1,1,1, roofColorOf(roofMat));
        }
      }
      rw--; rd--; lvl++;
      if(rw<0&&rd<0)break;
    }
  } else if(roofKind===1){ // flat with parapet (tower style)
    for(let dz=-d-1;dz<=d+1;dz++)for(let dx=-w-1;dx<=w+1;dx++){
      const edge=Math.abs(dx)===w+1||Math.abs(dz)===d+1;
      add(roofMat, wx+dx, ry+0.5, wz+dz, 1, edge?1:0.999, 1, roofColorOf(roofMat));
      if(edge) add(roofMat, wx+dx, ry+1.5, wz+dz, 0.8,1,0.8, roofColorOf(roofMat));
    }
  } else { // gable roof along x
    for(let lvl=0; lvl<=d; lvl++){
      const y=ry+lvl+0.5;
      for(let dx=-w-1; dx<=w+1; dx++){
        add(roofMat, wx+dx, y, wz-d+lvl, 1,1,1, roofColorOf(roofMat));
        add(roofMat, wx+dx, y, wz+d-lvl, 1,1,1, roofColorOf(roofMat));
      }
      if(lvl===d){
        for(let dx=-w-1;dx<=w+1;dx++) add(roofMat, wx+dx, y, wz, 1,1,1, roofColorOf(roofMat));
      }
    }
  }
}
function wallColorOf(m,dx,dz,fy){
  const base = {wallA:0xd9cbb2, wallB:0xc98d6b, wallC:0xe8e2d0, wallD:0xb7c4c9}[m];
  const c=new THREE.Color(base);
  if((dx+dz+fy)%3===0) c.multiplyScalar(0.94);
  return c;
}
function roofColorOf(m){
  return {roofR:0xb04a3a, roofB:0x5b7a99, roofG:0x5e7d4a, roofY:0xc9a24a}[m];
}

// place 12 buildings: try random spots on plateau
let seed=7;
function rnd(){ seed=(seed*16807)%2147483647; return seed/2147483647; }

const designs = [
  {w:2,d:2,wall:'wallA',roof:'roofR',kind:0,floors:1},
  {w:3,d:2,wall:'wallB',roof:'roofG',kind:2,floors:1},
  {w:2,d:3,wall:'wallC',roof:'roofB',kind:0,floors:2},
  {w:1,d:1,wall:'wallD',roof:'roofY',kind:1,floors:4}, // tower
  {w:3,d:3,wall:'wallA',roof:'roofY',kind:2,floors:1},
  {w:2,d:2,wall:'wallB',roof:'roofB',kind:0,floors:2},
];
let placed=0, tries=0;
const placedList=[];
while(placed<12 && tries<800){
  tries++;
  const a=rnd()*Math.PI*2, r=3+rnd()*(VILL_R-6);
  const cx=Math.round(vcx+Math.cos(a)*r), cz=Math.round(vcz+Math.sin(a)*r);
  const dsg=designs[placed%designs.length];
  if(!reserveFootprint(cx,cz,dsg.w+1,dsg.d+1)) continue;
  // avoid centre plaza overlap with path hub? path hub is centre; fine
  buildHouse(cx,cz,dsg.w,dsg.d,dsg.wall,dsg.roof,dsg.kind,dsg.floors);
  placedList.push([cx,cz]);
  placed++;
}
// ensure at least 12; fallback ring placement
let ringA=0;
while(placed<12){
  const cx=Math.round(vcx+Math.cos(ringA)*10), cz=Math.round(vcz+Math.sin(ringA)*10);
  ringA+=0.7;
  const dsg=designs[placed%designs.length];
  if(!reserveFootprint(cx,cz,dsg.w+1,dsg.d+1)) continue;
  buildHouse(cx,cz,dsg.w,dsg.d,dsg.wall,dsg.roof,dsg.kind,dsg.floors);
  placedList.push([cx,cz]);
  placed++;
}

// connect path through all buildings
for(let i=0;i<placedList.length-1;i++){
  carvePath(placedList[i][0],placedList[i][1],placedList[i+1][0],placedList[i+1][1]);
}
// rebuild path slabs for the newly carved cells (dedupe handled by Set)
for(const ci of pathCells){
  const x=ci%S, z=(ci/S)|0;
  const i=idx(x,z);
  if(surf[i]===2) continue;
  surf[i]=3;
  const h=hMap[i];
  terrainLists.path.push({x:x-half+0.5, y:h+0.04, z:z-half+0.5, sx:0.92, sy:0.12, sz:0.92, c:new THREE.Color().setHSL(0.08,0.06,0.42+(hash(x,z)-0.5)*0.1)});
}

// ---------- trees ----------
// 24 trees scattered on grass, away from village footprints/path
let trees=0, tTries=0;
while(trees<24 && tTries<900){
  tTries++;
  const x=Math.floor(rnd()*S), z=Math.floor(rnd()*S);
  const i=idx(x,z);
  if(surf[i]!==0) continue;
  if(usedCells.has(i)||pathCells.has(i)) continue;
  const nearVillage = Math.hypot(x-vcx,z-vcz)<VILL_R-4;
  if(nearVillage && rnd()<0.7) continue;
  // reserve small footprint
  let ok=true;
  for(let dz=-1;dz<=1;dz++)for(let dx=-1;dx<=1;dx++){ if(usedCells.has(idx(x+dx,z+dz))||pathCells.has(idx(x+dx,z+dz))) ok=false; }
  if(!ok) continue;
  for(let dz=-1;dz<=1;dz++)for(let dx=-1;dx<=1;dx++) usedCells.add(idx(x+dx,z+dz));
  const gy=hMap[i];
  const th=2+Math.floor(rnd()*3);
  const px=x-half+0.5, pz=z-half+0.5;
  for(let t=0;t<th;t++) add('trunk', px, gy+t+0.5, pz, 0.6,1,0.6, 0x6b4a2c);
  // canopy: blob of leaf voxels
  const cy=gy+th;
  const cr = 1+Math.floor(rnd()*2);
  for(let dy=0;dy<=cr;dy++)for(let dz=-cr;dz<=cr;dz++)for(let dx=-cr;dx<=cr;dx++){
    const dist=Math.abs(dx)+Math.abs(dy-cr/2)*1.2+Math.abs(dz);
    if(dist>cr+0.8) continue;
    if(dx===0&&dz===0&&dy<cr) continue;
    const lc = new THREE.Color().setHSL(0.30+rnd()*0.05, 0.55, 0.30+rnd()*0.12);
    add('leaf', px+dx, cy+dy+0.5, pz+dz, 0.95,0.95,0.95, lc);
  }
  trees++;
}

// ---------- create InstancedMeshes ----------
const groups = {};
for(const it of instances){
  (groups[it.m] ??= []).push(it);
}
for(const k in terrainLists) (groups[k] ??= []).push(...terrainLists[k]);

const meshList=[];
for(const key in groups){
  const arr=groups[key];
  const mesh=new THREE.InstancedMesh(boxGeo, mats[key], arr.length);
  mesh.castShadow = key!=='water' && key!=='window';
  mesh.receiveShadow = true;
  const M=new THREE.Matrix4();
  const col=new THREE.Color();
  arr.forEach((it,i)=>{
    M.makeScale(it.sx,it.sy,it.sz);
    M.setPosition(it.x,it.y,it.z);
    mesh.setMatrixAt(i,M);
    col.set(it.c ?? 0xffffff);
    mesh.setColorAt(i,col);
  });
  mesh.instanceMatrix.needsUpdate=true;
  if(mesh.instanceColor) mesh.instanceColor.needsUpdate=true;
  scene.add(mesh);
  meshList.push(mesh);
}

// ---------- camera orbit ----------
const centre = new THREE.Vector3(vcx-half+0.5, villageH+2, vcz-half+0.5);
let angle=0;
const radius = S*0.95; // ~68
const camY = villageH + 30;

function updateCamera(t){
  angle += 0.0016; // slow auto-rotation
  camera.position.set(centre.x+Math.cos(angle)*radius, camY, centre.z+Math.sin(angle)*radius);
  camera.lookAt(centre);
}

// ---------- day / night ----------
let night=false;
function setNight(v){
  night=v;
  if(v){
    scene.background.set(0x0b1026);
    scene.fog.color.set(0x0b1026);
    hemi.intensity=0.25; hemi.color.set(0x4a5a8a); hemi.groundColor.set(0x1a2030);
    sun.intensity=0.06; sun.color.set(0x334466);
    moon.intensity=0.5;
    mats.window.color.set(0xffd982);
  } else {
    scene.background.set(0x87ceeb);
    scene.fog.color.set(0x87ceeb);
    hemi.intensity=0.9; hemi.color.set(0xbfe3ff); hemi.groundColor.set(0x8a7a5a);
    sun.intensity=1.6; sun.color.set(0xfff2d8);
    moon.intensity=0.0;
    mats.window.color.set(0x2b3a4a); // dark glass in day
  }
}
setNight(false);
addEventListener('keydown',e=>{ if(e.code==='KeyN') setNight(!night); });

addEventListener('resize',()=>{
  camera.aspect=innerWidth/innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth,innerHeight);
});

// ---------- animate ----------
const clock=new THREE.Clock();
function tick(){
  requestAnimationFrame(tick);
  const t=clock.getElapsedTime();
  // gentle water bob
  const w=groups['water'];
  if(w){
    const mesh=meshList.find(m=>m.material===mats.water);
    if(mesh) mesh.position.y = Math.sin(t*1.2)*0.06;
  }
  updateCamera(t);
  renderer.render(scene,camera);
}
tick();
</script>
